const defaultAxis=()=>({schemaVersion:1,calendar:{kind:'gregorian',name:'公历',era:'公元',visibility:{year:true,month:true,day:true}},anchor:{date:{year:1,month:1,day:1},label:'第一章 · 故事起点'},coordinateUnit:'day',primaryTick:{unit:'year',step:1},legacyMode:'unmapped',tracks:[{id:'story-default',name:'未分组',color:'#7c8d73',side:'above'}],markers:[]});
