 const selectAnchorCard=id=>{const card=cards.find(c=>c.id===id);if(!card)return;const anchor={...draft.anchor,cardId:id,label:card.title||draft.anchor.label};delete anchor.chapterId;setCardHint('该卡片尚无可用的故事时间，请确认下方日期。');if(axis&&card.time?.story?.axisVersion===1){const sameCalendar=calendar.kind===axis.calendar.kind&&(calendar.kind!=='custom'||JSON.stringify(months.trim().split(/[,，\s]+/).map(Number))===JSON.stringify(axis.calendar.monthLengths));if(sameCalendar){anchor.date=coordinateToDate(card.time.story.start,axis.calendar);setCardHint('已带入该卡片的故事日期，请核对后确认；之后移动卡片不会自动改变起点。');}else setCardHint('历法已更改，未自动换算卡片日期；请确认下方日期。');}change('anchor',anchor);};
