 return <Sheet title={axis?'故事时间设置':'让故事拥有自己的时间'} submission={submission}><form className="sap-form" onSubmit={submit}><p className="sap-intro">先选择历法，再选择故事起点并确认日期。这里的位置独立保存，不改变叙述顺序、大纲或画布。</p><section className="sap-section"><h3><span>01</span> 用哪一种历法？</h3><div className="sap-options" role="group" aria-label="历法">{[['gregorian','公历'],['custom','自定义历法']].map(([kind,label])=><button type="button" key={kind} aria-pressed={calendar.kind===kind} onClick={()=>change('calendar',{...calendar,kind})}>{label}</button>)}</div><div className="sap-grid"><label>历法名称<input required maxLength={60} value={calendar.name||''} onChange={e=>calendarChange('name',e.target.value)}/></label><label>纪年／历的称呼<input maxLength={60} placeholder="如：公元、星历、第三纪元" value={calendar.era||''} onChange={e=>calendarChange('era',e.target.value)}/></label></div>{calendar.kind==='custom'&&<><label>一年中每个月的天数<input required value={months} onChange={e=>{setMonths(e.target.value);setConfirmed(false);}} placeholder="30, 30, 30, 30" inputMode="text"/></label><p className="sap-note">按顺序填写各月天数。自定义历每年重复同一组月份，不含未定义的闰月或闰年；日期由实际天数换算，不从文字名称猜测。</p></>}<fieldset className="sap-display"><legend>日期显示</legend>{[['year','年'],['month','月'],['day','日']].map(([key,label])=><label key={key}><input type="checkbox" checked={calendar.visibility?.[key]!==false} onChange={e=>calendarChange('visibility',{...calendar.visibility,[key]:e.target.checked})}/>{label}</label>)}</fieldset></section><section className="sap-section"><h3><span>02</span> 故事从哪里开始？</h3><div className="sap-options" role="group" aria-label="故事起点来源">{[['custom','自定义起点'],['card','选择剧情卡片']].map(([source,label])=><button type="button" key={source} aria-pressed={anchorSource===source} onClick={()=>{setAnchorSource(source);setConfirmed(false);if(source==='custom'){const anchor={...draft.anchor};delete anchor.cardId;change('anchor',anchor);setCardHint('');}}}>{label}</button>)}</div>{anchorSource==='card'&&<><label>起点剧情卡<select value={draft.anchor.cardId||''} onChange={e=>selectAnchorCard(e.target.value)}><option value="" disabled>请选择本作品的剧情卡</option>{cards.map(card=><option key={card.id} value={card.id}>{card.title}</option>)}</select></label>{!cards.length&&<p className="sap-note">还没有剧情卡，可以先使用自定义起点；不会自动创建卡片或章节。</p>}<p className="sap-note">{cardHint||'起点保留已确认的日期与名称，不会随卡片移动自动变化。'}</p></>}<label>起点名称<input required maxLength={120} value={draft.anchor.label} onChange={e=>change('anchor',{...draft.anchor,label:e.target.value})}/></label>{anchorSource==='custom'&&chapters.length>0&&<p className="sap-note">第一章：{chapters[0].title} · 锚点只是故事时间参照，不会改动正文。</p>}<DateFields calendar={calendar} legend="起点的故事日期" value={draft.anchor.date} onChange={date=>change('anchor',{...draft.anchor,date,...(chapters[0]&&anchorSource==='custom'?{chapterId:chapters[0].id}:{})})}/>{dateError&&<p className="sap-error" role="alert">{dateError} 已保留输入，请按所选历法核对日期。</p>}</section><section className="sap-section"><h3><span>03</span> 时间轴大刻度间隔</h3><p className="sap-note">设置时间轴上相邻两个带日期标签的大刻度，相隔多少时间；不是把一年分成几小格。</p><div className="sap-grid"><label>间隔数值<input required type="number" min="1" step="1" value={draft.primaryTick.step} onChange={e=>change('primaryTick',{...draft.primaryTick,step:e.target.value===''?'':Number(e.target.value)})}/></label><label>间隔单位<select value={draft.primaryTick.unit} onChange={e=>change('primaryTick',{...draft.primaryTick,unit:e.target.value})}><option value="year">年</option><option value="month">月</option><option value="day">日</option></select></label></div><p className="sap-note" aria-live="polite"><strong>{storyTickIntervalLabel(draft.primaryTick)}</strong></p><p className="sap-note">只调整刻度的显示间隔，不改变事件日期。事件仍可精确到任意一天；放大后可查看更细的日期，小刻度随缩放变化，不由这里的数字决定。</p></section><label className="sap-confirm"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/><span>已确认故事起点、历法与大刻度间隔</span></label><Footer submission={submission} submitDisabled={!confirmed||!!dateError||(anchorSource==='card'&&!draft.anchor.cardId)} label={axis?'保存设置':'开启故事时间线'}/></form></Sheet>;
