 const changeRelative=raw=>{setRelativeDraft(raw);if(raw===''){setDateError('');onChange('');return;}try{const offset=Number(raw),absolute=axis.anchor.coordinate+offset;if(!Number.isSafeInteger(offset)||!Number.isSafeInteger(absolute))throw new Error('请输入安全范围内的整数天数。');coordinateToDate(absolute,axis.calendar);setDateError('');onChange(absolute);}catch(e){setDateError(e.message);onChange('');}};
